ALTER TABLE public.license_requests ADD COLUMN active_plot_claim boolean NOT NULL DEFAULT false;
CREATE FUNCTION public.license_slot(f text,u text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN nullif(trim(f),'') IS NULL OR nullif(trim(u),'') IS NULL THEN NULL ELSE jsonb_build_array(upper(trim(f)),upper(trim(u)))::text END $$;
CREATE FUNCTION public.check_license_property(p_property_id uuid,p_floor text DEFAULT NULL,p_unit_number text DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE conflict text;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required';END IF;IF NOT EXISTS(SELECT 1 FROM public.licensing_plots WHERE id=p_property_id AND enabled) THEN RAISE EXCEPTION 'كود القطعة غير موجود / Plot code does not exist';END IF;SELECT tracking_id INTO conflict FROM public.license_requests WHERE property_id=p_property_id AND ((status NOT IN('issued','rejected') AND deleted_at IS NULL) OR(status='issued' AND expires_at>now())) LIMIT 1;RETURN conflict;END $$;
REVOKE ALL ON FUNCTION public.check_license_property(uuid,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.check_license_property(uuid,text,text) TO authenticated;
CREATE FUNCTION public.validate_license_property() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.licensing_plots;original public.license_requests;conflict text;BEGIN
 IF TG_OP='UPDATE' THEN IF NEW.property_id IS DISTINCT FROM OLD.property_id OR NEW.unit_id IS DISTINCT FROM OLD.unit_id OR NEW.floor IS DISTINCT FROM OLD.floor OR NEW.unit_number IS DISTINCT FROM OLD.unit_number THEN RAISE EXCEPTION 'Property and unit are read-only';END IF;NEW.active_plot_claim:=NEW.kind='new' AND ((NEW.status NOT IN('issued','rejected') AND NEW.deleted_at IS NULL) OR(NEW.status='issued' AND NEW.expires_at>now()));RETURN NEW;END IF;
 IF NEW.kind<>'new' THEN SELECT * INTO original FROM public.license_requests WHERE id=NEW.parent_id AND user_id=NEW.user_id FOR UPDATE;IF NOT FOUND OR original.status<>'issued' OR original.expires_at IS NULL THEN RAISE EXCEPTION 'Issued owned license required';END IF;IF NEW.kind<>'renewal' AND original.expires_at<=now() THEN RAISE EXCEPTION 'التعديل متاح فقط على ترخيص ساري / Amendments require an active license';END IF;NEW.property_id:=original.property_id;NEW.unit_id:=original.unit_id;NEW.floor:=original.floor;NEW.unit_number:=original.unit_number;NEW.active_plot_claim:=false;RETURN NEW;END IF;
 SELECT * INTO p FROM public.licensing_plots WHERE id=NEW.property_id AND enabled;IF NOT FOUND THEN RAISE EXCEPTION 'كود القطعة غير موجود / Plot code does not exist';END IF;IF NEW.district IS DISTINCT FROM p.district OR NEW.plot_number IS DISTINCT FROM p.code THEN RAISE EXCEPTION 'القطعة لا تتبع الحي المختار / Plot does not belong to the selected district';END IF;
 NEW.floor:=nullif(trim(NEW.floor),'');NEW.unit_number:=nullif(trim(NEW.unit_number),'');IF p.has_units OR p.code IN('H5','SI4','N1') THEN NEW.unit_id:=public.license_slot(NEW.floor,NEW.unit_number);IF NEW.unit_id IS NULL THEN RAISE EXCEPTION 'الطابق ورقم الوحدة مطلوبان';END IF;ELSE NEW.floor:=NULL;NEW.unit_number:=NULL;NEW.unit_id:=NULL;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p.id::text,0));
 UPDATE public.license_requests SET active_plot_claim=false WHERE property_id=p.id AND active_plot_claim AND status='issued' AND expires_at<=now();
 conflict:=public.check_license_property(p.id,NEW.floor,NEW.unit_number);IF conflict IS NOT NULL THEN RAISE EXCEPTION 'هذه القطعة مرخصة بالفعل أو قيد المراجعة / This plot is already licensed or under review: %',conflict USING ERRCODE='23505';END IF;
 IF EXISTS(SELECT 1 FROM public.license_requests WHERE property_id=p.id AND user_id=NEW.user_id AND status='issued' AND expires_at<=now()) THEN RAISE EXCEPTION 'انتهى الترخيص؛ استخدم تجديد / License expired; use Renew' USING ERRCODE='P0001';END IF;
 NEW.active_plot_claim:=true;IF p.latitude IS NOT NULL AND p.longitude IS NOT NULL THEN NEW.selected_location:=jsonb_build_object('lat',p.latitude,'lng',p.longitude);END IF;RETURN NEW;END $$;
CREATE TRIGGER aa_validate_license_property BEFORE INSERT OR UPDATE ON public.license_requests FOR EACH ROW EXECUTE FUNCTION public.validate_license_property();
CREATE UNIQUE INDEX license_one_active_plot ON public.license_requests(property_id) WHERE active_plot_claim;
CREATE UNIQUE INDEX license_one_open_followup ON public.license_requests(parent_id) WHERE kind<>'new' AND deleted_at IS NULL AND status NOT IN('issued','rejected');
CREATE INDEX license_requests_property_lookup ON public.license_requests(property_id);CREATE INDEX licensing_plots_district ON public.licensing_plots(district);
CREATE FUNCTION public.plot_availability(p_district text) RETURNS TABLE(id uuid,code text,district text,has_units boolean,latitude double precision,longitude double precision,blocked boolean,renewal_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.code,p.district,p.has_units,p.latitude,p.longitude,EXISTS(SELECT 1 FROM public.license_requests r WHERE r.property_id=p.id AND ((r.status NOT IN('issued','rejected') AND r.deleted_at IS NULL) OR(r.status='issued' AND r.expires_at>now()))),(SELECT r.id FROM public.license_requests r WHERE r.property_id=p.id AND r.user_id=auth.uid() AND r.status='issued' AND r.expires_at<=now() ORDER BY r.expires_at DESC LIMIT 1) FROM public.licensing_plots p WHERE auth.uid() IS NOT NULL AND p.enabled AND p.district=p_district ORDER BY p.code $$;
REVOKE ALL ON FUNCTION public.plot_availability(text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.plot_availability(text) TO authenticated;